import json,re
from pathlib import Path
manifest=Path('/mnt/data/LSF/results/nopv/agentic_rule_full_data_gpt54_adaptive/all_docs/q09_list_all_49_cfr_section_numbers_cited_as_the_basis_for_alleg.manifest.json')
with open(manifest) as f:
    docs=json.load(f)['documents']

stop_re=re.compile(r'"'^(proposed civil penalty|warning items|proposed compliance order|response to this notice)'"\\b',re.I)
start_re=re.compile(r'probable violation',re.I)
item_re=re.compile(r'"'^'"\\s*(\\d+)\\.\\s*(.*)"'$'"')
cite_re=re.compile(r'(?:49\\s*C\\.?F\\.?R\\.?\\s*)?§+\\s*([0-9]+\\.[0-9]+(?:\\([A-Za-z0-9]+\\))*)')

def split_pages(text):
    return re.split(r'\\f+', text)

def lines(text):
    out=[]
    for pno,page in enumerate(split_pages(text),1):
        for lno,line in enumerate(page.splitlines(),1):
            out.append((pno,lno,line))
    return out

def item_blocks(text):
    ls=lines(text)
    in_sec=False
    blocks=[]
    cur=[]
    pending=False
    for rec in ls:
        line=rec[2].strip()
        low=line.lower()
        if not in_sec:
            if 'items inspected' in low and 'probable violation' in low:
                in_sec=True
            continue
        if stop_re.match(line):
            break
        m=item_re.match(line)
        if m:
            if cur: blocks.append(cur)
            cur=[rec]
            pending=True
            continue
        if pending and not line:
            cur.append(rec)
            continue
        cur.append(rec)
        pending=False
    if cur: blocks.append(cur)
    return blocks

correct=0
for d in docs:
    text=Path(d['doc_path']).read_text(errors='ignore')
    preds=[]
    seen=set()
    for block in item_blocks(text):
        for _,_,line in block[:6]:
            m=cite_re.search(line)
            if m:
                c=m.group(1)
                if c not in seen:
                    preds.append(c); seen.add(c)
                break
    gt=[re.sub(r'"'^(49'"\\s*C\\.?F\\.?R\\.?\\s*§\\s*)','',x).strip() for x in d['ground_truth']]
    if set(preds)==set(gt):
        correct+=1
print('heading exact matches',correct,'/',len(docs),correct/len(docs))
PY"

