    return (
        span.get("page_no"),
        span.get("paragraph_no"),
        span.get("line_no"),
        span.get("text"),
    )


def _sort_key(span: dict[str, Any]) -> tuple[Any, ...]:
    return (
        span.get("page_no", 10**9),
        span.get("paragraph_no", 10**9),
        span.get("line_no", 10**9),
        span.get("text", ""),
    )


def _list_rule_files(rules_dir: Path, rule_names: list[str] | None = None) -> list[Path]:
    if rule_names:
        files = [rules_dir / f"{name}.py" for name in rule_names]
        return [path for path in files if path.exists()]
    return sorted(path for path in rules_dir.glob("rule_*.py") if path.is_file())


def _apply_rule_files(document: dict[str, Any], rule_files: list[Path]) -> dict[str, Any]:
    spans: list[dict[str, Any]] = []
    rules_applied: list[str] = []
    rules_no_hits: list[str] = []
    rule_errors: list[str] = []

    for rule_file in rule_files:
        rule_name = rule_file.stem
        try:
            rule_fn = _load_rule_fn(rule_file)
            raw_result = rule_fn(document)
        except Exception as exc:
            rule_errors.append(f"{rule_name}: {exc}")
            rules_no_hits.append(rule_name)
            continue

        if not isinstance(raw_result, list):
            rules_no_hits.append(rule_name)
            continue

        coerced = [_coerce_span(item) for item in raw_result]
        cleaned = [item for item in coerced if item]
        if cleaned:
            spans.extend(cleaned)
            rules_applied.append(rule_name)
        else:
            rules_no_hits.append(rule_name)

    deduped: list[dict[str, Any]] = []
    seen: set[tuple[Any, ...]] = set()
    for span in spans:
        key = _span_key(span)
        if key in seen:
            continue
        seen.add(key)
        deduped.append(span)

    deduped.sort(key=_sort_key)
    retrieved_text = "\n\n".join(span["text"] for span in deduped) if deduped else ""

import re


_PART_RE = r"(?:40|1\d\d|2\d\d)\.\d+(?:\([A-Za-z0-9]+\))*"
_HEADING_RE = re.compile(
    rf"^\s*(?:\d+\.\s*)?(?:49\s*C\.?\s*F\.?\s*R\.?\s*)?§\s*({_PART_RE})\b",
    re.IGNORECASE,
)
_ITEM_ONLY_RE = re.compile(r"^\s*\d+\.\s*$")
_STOP_RE = re.compile(
    r"^(proposed civil penalty|warning items|proposed compliance order|response to this notice)\b",
    re.IGNORECASE,
)
_ALLEGATION_RE = re.compile(
    r"\b(failed|did not|didn't|was not|were not|has not|have not)\b",
    re.IGNORECASE,
)
_CONCLUSION_RE = re.compile(r"^\s*(therefore|thus)\b", re.IGNORECASE)
_SUBSECTION_LINE_RE = re.compile(r"^\s*\([A-Za-z0-9ivxlcdm]+\)", re.IGNORECASE)


def _start_idx(paragraphs):
    for idx, para in enumerate(paragraphs):
        text = para["text"].lower()
        if "item inspected" in text or "items inspected" in text:
            window = " ".join(p["text"].lower() for p in paragraphs[idx : idx + 2])
            if "probable violation" in window:
                return idx + 1
    return None


def _is_heading(text):
    return bool(_HEADING_RE.match(text.replace("\n", " ")))


def _trim_paragraphs(paragraphs):
    start = _start_idx(paragraphs)
    if start is None:
        return []

    trimmed = []
    for para in paragraphs[start:]:
        text = para["text"].strip()
        if _STOP_RE.match(text):
            break
        trimmed.append(para)
    return trimmed


def _build_blocks(paragraphs):
    blocks = []
    current = []
    pending_item = None

    for para in paragraphs:
        text = para["text"].strip()
        if _ITEM_ONLY_RE.match(text):
            if current:
                blocks.append(current)
                current = []
            pending_item = para
            continue

        if _is_heading(text):
            if current:
                blocks.append(current)
            current = [pending_item] if pending_item else []
            current.append(para)
            pending_item = None
            continue

        if current:
            current.append(para)

    if current:
        blocks.append(current)
    return blocks


def _select_spans(block):
    spans = []
    seen = set()

    heading_idx = None
    allegation_idx = None
    for idx, para in enumerate(block):
        text = para["text"].strip()
        if heading_idx is None and _is_heading(text):
            heading_idx = idx
        if allegation_idx is None and _ALLEGATION_RE.search(text):
            allegation_idx = idx

    if heading_idx is None or allegation_idx is None or allegation_idx < heading_idx:
        return []

    last_reg_idx = heading_idx
    for idx in range(heading_idx + 1, allegation_idx):
        text = block[idx]["text"].strip()
        if _SUBSECTION_LINE_RE.match(text) or not _ALLEGATION_RE.search(text):
            last_reg_idx = idx

    keep_idxs = list(range(heading_idx, last_reg_idx + 1))
    keep_idxs.append(allegation_idx)

    for idx in range(allegation_idx + 1, min(len(block), allegation_idx + 3)):
        if _CONCLUSION_RE.match(block[idx]["text"].strip()):
            keep_idxs.append(idx)
            break

    for idx in keep_idxs:
        para = block[idx]
        key = (para["page_no"], para["paragraph_no"])
        if key in seen:
            continue
        seen.add(key)
        spans.append(
            {
                "text": para["text"],
                "page_no": para["page_no"],
                "paragraph_no": para["paragraph_no"],
            }
        )

    return spans


def rule_violation_blocks(doc: dict) -> list[dict]:
    try:
        paragraphs = _trim_paragraphs(doc.get("paragraphs", []))
        spans = []
        for block in _build_blocks(paragraphs):
            spans.extend(_select_spans(block))
        return spans
    except Exception:
        return []

import re


_PART_RE = r"(?:40|1\d\d|2\d\d)\.\d+(?:\([A-Za-z0-9]+\))*"
_CITE_RE = re.compile(
    rf"((?:49\s*C\.?\s*F\.?\s*R\.?\s*)?§\s*{_PART_RE}|section[s]?\s+{_PART_RE})",
    re.IGNORECASE,
)
_STOP_RE = re.compile(
    r"^(proposed civil penalty|warning items|proposed compliance order|response to this notice)\b",
    re.IGNORECASE,
)
_ALLEGATION_RE = re.compile(
    r"\b(failed|did not|didn't|was not|were not|has not|have not)\b",
    re.IGNORECASE,
)
_CONCLUSION_RE = re.compile(r"^\s*(therefore|thus)\b", re.IGNORECASE)
_SECTION_START_RE = re.compile(r"(item inspected|items inspected)", re.IGNORECASE)


def _line_window(lines):
    started = False
    for line in lines:
        text = line["text"].strip()
        if not started:
            if _SECTION_START_RE.search(text):
                started = True
            continue
        if _STOP_RE.match(text):
            break
        yield line


def rule_citation_lines(doc: dict) -> list[dict]:
    try:
        spans = []
        for line in _line_window(doc.get("lines", [])):
            text = line["text"].strip()
            if not text:
                continue
            if not (_ALLEGATION_RE.search(text) or _CONCLUSION_RE.match(text)):
                continue
            if not _CITE_RE.search(text):
                continue
            spans.append(
                {
                    "text": line["text"],
                    "page_no": line["page_no"],
                    "line_no": line["line_no"],
                }
            )
        return spans
    except Exception:
        return []

